"""Bundled plastic materials — GENERATED by scripts/build_bundle.py.
Do not edit by hand.

    from threejs_materials import plastic
    plastic.acrylic()

Each material is a factory returning a fresh PbrProperties; the signature
exposes only the overrides that make sense: `color` (colorable; raw metals
omit it), `roughness`, `scale=(u, v)` + `rotation` degrees (textured),
`thickness` (transmissive).
"""
import functools
import warnings
from pathlib import Path

from threejs_materials.library import PbrProperties

_ASSETS = Path(__file__).parent / "_assets"

def acrylic(color=None, roughness=None, thickness=None):
    m = PbrProperties.from_dict({   'id': 'acrylic',
    'name': 'acrylic',
    'source': 'physicallybased',
    'url': 'https://physicallybased.info/',
    'license': 'CC0 1.0',
    'values': {   'color': [   0.9999999999999999,
                               0.9999999999999999,
                               0.9999999999999999],
                  'metalness': 0.0,
                  'roughness': 0.0,
                  'ior': 1.4905,
                  'transmission': 1.0,
                  'thickness': 1.0,
                  'dispersion': 0.376081233546446},
    'textures': {}})
    if color is not None:
        m = m.override(color=color)
    if roughness is not None:
        m = m.override(roughness=roughness)
    if thickness is not None:
        m = m.override(thickness=thickness)
    return m

