# Deprecated aliases — removed in the next major.

@functools.wraps(plastic)
def plastic_clean(*args, **kwargs):
    warnings.warn(
        "plastic_clean() is deprecated, use plastic() instead.",
        DeprecationWarning,
        stacklevel=2,
    )
    return plastic(*args, **kwargs)
